# BGP Constants
BGP_PORT = 179
BGP_VERSION = 4
BGP_MSG_OPEN = 1
BGP_MSG_KEEPALIVE = 4
BGP_MSG_NOTIFICATION = 3
BGP_HEADER_LENGTH = 19

# Error Codes
ERROR_CODE_OPEN_MSG_ERROR = 2
SUBCODE_BAD_BGP_IDENTIFIER = 4
SUBCODE_UNACCEPTABLE_HOLD_TIME = 3
SUBCODE_BAD_PEER_AS = 2
SUBCODE_UNSUPPORTED_VERSION = 1

def craft_bgp_header(msg_type, msg_length):
    """Crafts the 19-byte BGP header."""
    marker = b'\xff' * 16
    length = struct.pack('!H', msg_length + BGP_HEADER_LENGTH)
    return marker + struct.pack('!B', msg_type) + length

def craft_bgp_open(version, my_as, hold_time, bgp_id, opt_params=b''):
    """Crafts a BGP OPEN message body."""
    opt_len = len(opt_params)
    body = struct.pack('!B', version)
    body += struct.pack('!H', my_as)
    body += struct.pack('!H', hold_time)
    body += struct.pack('!I', bgp_id)
    body += struct.pack('!B', opt_len)
    body += opt_params
    return body

def parse_bgp_message(data):
    """Parses a BGP message and returns type, length, and payload."""
    if len(data) < BGP_HEADER_LENGTH:
        return None, None, None
    marker = data[:16]
    if marker != b'\xff' * 16:
        return None, None, None
    msg_type = data[16]
    msg_length = struct.unpack('!H', data[17:19])[0]
    payload = data[19:19 + (msg_length - BGP_HEADER_LENGTH)]
    return msg_type, msg_length, payload

def parse_bgp_open(open_msg):
    """Parses a BGP OPEN message payload."""
    if len(open_msg) < 10:
        return None
    version = open_msg[0]
    my_as = struct.unpack('!H', open_msg[1:3])[0]
    hold_time = struct.unpack('!H', open_msg[3:5])[0]
    bgp_id = struct.unpack('!I', open_msg[5:9])[0]
    opt_len = open_msg[9]
    opt_params = open_msg[10:10+opt_len]
    return {
        'version': version,
        'my_as': my_as,
        'hold_time': hold_time,
        'bgp_id': bgp_id,
        'opt_params': opt_params
    }

def send_notification(sock, error_code, subcode, data=b''):
    """Sends a BGP NOTIFICATION message."""
    notif_body = struct.pack('!BB', error_code, subcode) + data
    header = craft_bgp_header(BGP_MSG_NOTIFICATION, len(notif_body))
    sock.sendall(header + notif_body)

